use chrono::NaiveDate; use exchange_hours::{Exchange,MarketHoursKey,ExchangeCalendar};
fn main(){let names=["nasdaq", "nyse", "cme", "cbot", "comex", "nymex", "cfe", "coinbase_derivatives", "eurex", "iceus", "asx", "nzx", "tse", "nse_india", "hkex", "sgx_securities", "sse", "lse", "xetra", "six", "euronext_paris", "euronext_amsterdam", "euronext_brussels", "euronext_lisbon", "bme", "nasdaq_stockholm", "nasdaq_helsinki", "nasdaq_copenhagen", "borsa_istanbul", "tsx", "tadawul", "b3", "globex_equity_index", "globex_energy", "globex_grains", "globex_fx", "globex_interest_rates", "globex_livestock", "globex_cryptocurrency", "eurex", "ice_us_sugar", "globex_nikkei_225_dollar", "eurex_fixed_income", "oanda_fx", "oanda_try_fx", "oanda_metals", "oanda_us_index_cfd", "oanda_us_bond_cfd", "oanda_us_commodity_cfd", "oanda_brent", "oanda_china50_cfd", "oanda_singapore30_cfd"];let first=NaiveDate::from_ymd_opt(2025,1,1).unwrap();let sample=NaiveDate::from_ymd_opt(2025,6,10).unwrap();let(mut complete,mut incomplete,mut no)=(0,0,0);for name in names {let c=if let Ok(x)=name.parse::<Exchange>(){ExchangeCalendar::new(x)}else{ExchangeCalendar::for_market_hours_key(name.parse::<MarketHoursKey>().unwrap())};let h=c.holiday_coverage().unwrap();if !h.windows().iter().any(|(a,b)|*a<=sample&&sample<=*b){no+=1;println!("{name}: no2025coverage");continue;} let mut missing=0;for g in c.coverage().gaps(){if g.range().first()>h.last(){break;} if g.range().last()>=first && g.reason()!=exchange_hours::CoverageGapReason::ResolutionEdge {missing+=1;}}if missing==0{complete+=1;println!("{name}: complete");}else{incomplete+=1;println!("{name}: incomplete {missing}dates");}}println!("COUNTS complete={complete} incomplete={incomplete} no2025coverage={no}");}